// Format the response for the webhook
const workflowConfig = $('Workflow Configuration').first().json;
const agentOutput = $input.first().json;

// Extract sessionId from workflow configuration
const sessionId = workflowConfig.sessionId || 'default-session';

// Extract reply from agent output
const reply = agentOutput.output || agentOutput.text || '';

// Build toolCalls array from execution metadata
const toolCalls = [];

// Check if there's tool usage information in the agent output
if (agentOutput.intermediateSteps && Array.isArray(agentOutput.intermediateSteps)) {
  agentOutput.intermediateSteps.forEach((step, index) => {
    if (step.action && step.action.tool) {
      toolCalls.push({
        tool: step.action.tool,
        input: step.action.toolInput || {},
        output: step.observation || ''
      });
    }
  });
}

// Return formatted response
return {
  json: {
    sessionId: sessionId,
    reply: reply,
    toolCalls: toolCalls
  }
};

